from functools import lru_cache
from itertools import combinations
rows=(5,4,3,3,3,4,4,2,4)
cols=(5,2,3,5,5,3,3,1,5)
n=len(rows)
m=len(cols)
# Precompute row patterns by sum
patterns={}
for r in set(rows):
    arr=[]
    for comb in combinations(range(m), r):
        v=[0]*m
        for j in comb:
            v[j]=1
        arr.append(tuple(v))
    patterns[r]=arr

@lru_cache(None)
def dp(i, rem):
    if i==n:
        return 1 if all(x==0 for x in rem) else 0
    need=rows[i]
    total=0
    for pat in patterns[need]:
        new=[]
        ok=True
        for c,p in zip(rem,pat):
            if p>c:
                ok=False
                break
            new.append(c-p)
        if ok:
            total += dp(i+1, tuple(new))
    return total

print(dp(0, cols))
